def triangular_numbers(n):
    """
    Returns triangular numbers up to n.
    A triangular number is the sum of the natural numbers from 1 to k.
    The k-th triangular number is given by T_k = k * (k + 1) // 2.
    """
    return [
        k * (k + 1) // 2
        for k in range(1, n + 1)
        if k * (k + 1) // 2 <= n
    ]

