def has_three_sum_zero(nums):
    """
    Returns True if there exist three distinct indices i, j, k such that
    nums[i] + nums[j] + nums[k] == 0, otherwise False.
    Uses a functional approach with itertools.combinations.
    """
    from itertools import combinations

    # Generate all combinations of three distinct indices and check their sum
    return any(
        nums[i] + nums[j] + nums[k] == 0
        for i, j, k in combinations(range(len(nums)), 3)
    )

