def count_special_multiples(n: int) -> int:
    """
    Counts the number of integers in the range [0, n-1] that are
    multiples of 11 or 13 and contain the digit '7'.

    Args:
        n: The upper bound (exclusive).

    Returns:
        The count of such integers.
    """
    return sum(
        1 for i in range(n)
        if (i % 11 == 0 or i % 13 == 0) and '7' in str(i)
    )

